changeSet.sql:
ALTER TABLE drink_catalog ADD CONSTRAINT ck_drink_catalog_volume CHECK (volume_ml IS NULL OR volume_ml BETWEEN 1 AND 10000);
ALTER TABLE drink_catalog ADD CONSTRAINT ck_drink_catalog_kcal CHECK (kcal_per_serving IS NULL OR kcal_per_serving BETWEEN 0 AND 10000);
ALTER TABLE drink_library ADD CONSTRAINT ck_drink_library_volume CHECK (volume_ml IS NULL OR volume_ml BETWEEN 1 AND 10000);
ALTER TABLE drink_library ADD CONSTRAINT ck_drink_library_kcal CHECK (kcal_per_serving IS NULL OR kcal_per_serving BETWEEN 0 AND 10000);

SELECT set_config('vereint.rls_bypass', 'on', true);
UPDATE drink_catalog SET
    volume_ml = COALESCE(volume_ml, (SELECT l.volume_ml FROM drink_library l WHERE l.id = drink_catalog.library_drink_id)),
    kcal_per_serving = COALESCE(kcal_per_serving, (SELECT l.kcal_per_serving FROM drink_library l WHERE l.id = drink_catalog.library_drink_id))
WHERE library_drink_id IS NOT NULL;
